  const x0 = Math.max(0, Math.min(sw - rw, cx - rw / 2)), y0 = Math.max(0, Math.min(sh - rh, cy - rh / 2));
  const layer = document.createElement('canvas'); layer.width = W; layer.height = H;
  const lc = layer.getContext('2d');
