    lc.save(); lc.lineJoin = 'round';
    lc.strokeStyle = rshBuildBevelGradient(proxy, o.bevelStyle || 'gold'); lc.lineWidth = 20 * avg; lc.stroke(path);
    lc.strokeStyle = 'rgba(255,255,255,0.65)'; lc.lineWidth = 5 * avg; lc.stroke(path);
