function pdfedAnimPickerOutside(e) { const box = document.getElementById('pdfedAnimPicker'); if (box && !box.contains(e.target)) pdfedCloseAnimPicker(); }
function pdfedAnimPickerKey(e) { if (e.key === 'Escape') pdfedCloseAnimPicker(); }

