    lab.className = 'pa-lab'; lab.innerHTML = 'CUSTOM <i>built by Kadessa</i>'; grid.className = 'pa-grid';
    const cb = document.createElement('button'); cb.type = 'button'; cb.className = 'pa-tile on';
